cd '/filesystem' || exit 1
cd /filesystem/final_batch4__structural_task5_wind_diaphragm_shear__blind && python3 - <<'EOF'
import re
txt=open('project/20_survey/NDDC-A2_Federated_Model_2026.ifc').read()
lines=txt.splitlines()
ents={}
for ln in lines:
    m=re.match(r'#(\d+)\s*=\s*([A-Z0-9]+)\s*\((.*)\)\s*;\s*$', ln)
    if m: ents[int(m.group(1))]=(m.group(2),m.group(3))
# property single values
pv={}
for i,(t,a) in ents.items():
    if t=='IFCPROPERTYSINGLEVALUE':
        m=re.match(r"\s*'([^']*)'\s*,\s*\$\s*,\s*(.+?)\s*,\s*(.*)$",a)
        if m:
            name,val=m.group(1),m.group(2)
            mm=re.match(r'IFC[A-Z]+\((.*)\)',val)
            pv[i]=(name, mm.group(1) if mm else val)
# property sets
psets={}
for i,(t,a) in ents.items():
    if t=='IFCPROPERTYSET':
        m=re.match(r"\s*'[^']*'\s*,\s*#\d+\s*,\s*'([^']*)'\s*,\s*\$[^,]*,\s*\(([^)]*)\)",a)
        if m:
            ids=[int(x[1:]) for x in m.group(2).split(',') if x.strip().startswith('#')]
            psets[i]=(m.group(1),ids)
# rel defines
relps={}
for i,(t,a) in ents.items():
    if t=='IFCRELDEFINESBYPROPERTIES':
        m=re.match(r"[^,]*,[^,]*,[^,]*,[^,]*,\s*\(([^)]*)\),\s*#(\d+)",a)
        if m:
            objs=[int(x[1:]) for x in m.group(1).split(',') if x.strip().startswith('#')]
            for o in objs: relps.setdefault(o,[]).append(int(m.group(2)))
for i,(t,a) in ents.items():
    if t in ('IFCWALL','IFCSLAB','IFCOPENINGELEMENT','IFCPLATE','IFCMEMBER','IFCSHADINGDEVICE'):
        name=re.match(r"\s*'[^']*'\s*,\s*#\d+\s*,\s*'([^']*)'\s*,\s*'([^']*)'",a)
        print(i,t,name.groups() if name else a[:120])
        for p in relps.get(i,[]):
            nm,ids=psets[p]
            print('  ',nm,{pv[k][0]:pv[k][1] for k in ids if k in pv})
EOF

