exit_code=0
import numpy as np, csv, math
import a2data as D

V=115.0; KD=0.85; KZT=1.19; ZG=3941.02
KE=math.exp(-0.0000362*ZG)
def Kz(z):
    z=max(z,15.0)
    return 2.01*(z/900.0)**(2/9.5)
def q(z): return 0.00256*Kz(z)*KZT*KD*KE*V*V
H_ROOF=28.0
QH=q(H_ROOF)
AZ={0:0,45:45,90:90,135:135,180:180,225:225,270:270,315:315}
CP={}
with open('/filesystem/final_batch4__structural_task5_wind_diaphragm_shear__blind/project/40_wind/WT-2026-07_Cp_by_azimuth.csv') as fh:
    for r in csv.DictReader(fh):
        CP[(r['patch_id'],int(r['azimuth_deg']))]=float(r['cp'])

def patch_loads(panel, az):
    """return (Rroof vector kip, Rbase vector kip, total p*A kip, area) for a panel at azimuth"""
    L=panel['s1']-panel['s0']; top=panel['top']; n=D.LINES[panel['line']]['normal']
    out=[]
    # bands
    bands=[('B1',0,7),('B2',7,14),('B3',14,21),('B4',21,28)]
    for (bn,z0,z1) in bands:
        key=(panel['mark']+'-'+bn,az)
        cp=CP[key]
        p=QH*cp
        A=L*(z1-z0)
        zc=(z0+z1)/2
        Fr=p*A/1000.0
        Rroof=Fr*zc/H_ROOF
        out.append(dict(band=bn,cp=cp,p=p,A=A,z=zc,F=Fr,Rroof=Rroof,area=A))
    # parapet
    key=(panel['mark']+'-P',az)
    cp=CP[key]
    qp=q(top)
    p=qp*cp
    A=L*(top-H_ROOF)
    zc=(H_ROOF+top)/2
    Fr=p*A/1000.0
    Rroof=Fr*zc/H_ROOF
    out.append(dict(band='P',cp=cp,p=p,A=A,z=zc,F=Fr,Rroof=Rroof,area=A))
    return out

def scenario_loads(az, tors=None):
    """returns list of (line, s0, s1, w_kip_per_ft signed along inward normal) and total vector,
       for base case; if tors is ('+',B) applies 0.75 and torsion"""
    segs=[]
    tot=np.zeros(2)
    for p in D.panels():
        n=np.array(D.LINES[p['line']]['normal'],float)
        for b in patch_loads(p,az):
            Rv=b['Rroof']*n
            w=b['Rroof']/(p['s1']-p['s0'])
            segs.append((p['line'],p['s0'],p['s1'],w,n))
            tot+=Rv
    fac=1.0
    if tors:
        fac=0.75
        segs=[(l,a,b,w*fac,n) for (l,a,b,w,n) in segs]
        tot*=fac
    return segs,tot

def line_summary(az):
    segs,tot=scenario_loads(az)
    per={l:np.zeros(2) for l in D.LINES}
    for (l,a,b,w,n) in segs:
        per[l]+=w*(b-a)*n
    return tot,per

if __name__=='__main__':
    print('Ke',KE,'Kz28',Kz(28),'qh',QH,'qp31',q(31),'qp36',q(36))
    for az in [0,45,90,135,180,225,270,315]:
        tot,per=line_summary(az)
        print(az,'total %.2f %.2f'%(tot[0],tot[1]),'  '+'  '.join('%s:(%.1f,%.1f)'%(l,v[0],v[1]) for l,v in per.items()))
