sys.path.insert(0,'/tmp/ahpele/work')
import numpy as np, fastmodel as F, a2data as D, wind as W
SC=[('W01',0,None),('W02',45,None),('W03',90,None),('W04',135,None),('W05',180,None),('W06',225,None),
    ('W07',270,None),('W08',315,None),('W09',0,(1,240)),('W10',0,(-1,240)),('W11',90,(1,180)),('W12',90,(-1,180))]
SC4=[('W01',0,None),('W03',90,None),('W05',180,None),('W07',270,None)]
SC6=SC4+[('W09',0,(1,240)),('W11',90,(1,180))]

def eval_design(deck, chordA, H=5.0, scenarios=SC, want_zone=True):
    dg={z:D.DECK_BY_CODE[deck[z]]['Gp'] for z in D.ZONES}
    m=F.build(H,dg,chordA)
    maxdef={'X':0,'Y':0}; def_by={}
    zone_max={z:0.0 for z in D.ZONES}
    chord_max={c[0]:0.0 for c in D.CHORD_LINES}
    panelshear={p['mark']:0.0 for p in D.panels()}
    pierdrift=0.0; shearmax=0.0; reac={}
    for sid,az,tors in scenarios:
        F.apply_scenario(m,az,tors); u=F.solve(m); r=F.results(m,u)
        for ax in ('X','Y'): maxdef[ax]=max(maxdef[ax],r['defl'][ax])
        def_by[sid]=r['defl']
        sh=np.abs(r['shear']); shearmax=max(shearmax,sh.max())
        if want_zone:
            for z in D.ZONES:
                sel=m.zone_of_elem==z
                if sel.any(): zone_max[z]=max(zone_max[z],sh[sel].max())
        for lid,v in r['chord'].items(): chord_max[lid]=max(chord_max[lid],v)
        # pier/panel
        ps={}
        for pr in m.piers:
            ud=u[2*pr['node']+pr['dof']]
            pierdrift=max(pierdrift,abs(ud)*12.0)
            ps[pr['panel']]=ps.get(pr['panel'],0.0)+pr['k']*ud
        for pn,v in ps.items(): panelshear[pn]=max(panelshear[pn],abs(v))
        reac[sid]=dict(r['reac'])
    return dict(maxdef=maxdef,def_by=def_by,zone_max=zone_max,chord_max=chord_max,
                pierdrift=pierdrift,shearmax=shearmax,reac=reac,m=m,panelshear=panelshear)

def cost(deck,chordA,zone_max=None,panelshear=None):
    dc=sum(D.zone_area(z)*D.DECK_BY_CODE[deck[z]]['cost'] for z in D.ZONES)
    cc=0
    for (lid,typ,p0,p1) in D.CHORD_LINES:
        A=chordA[lid]; sec=[s for s in D.SECTIONS if abs(s[1]-A)<1e-9][0]
        L=math.hypot(p1[0]-p0[0],p1[1]-p0[1]); cc+=L*sec[2]*2.85
    return dc+cc, dc, cc

