import numpy as np, fastdesign as G, a2data as D
# Pareto deck options sorted by G'
opts=sorted([d for d in D.DECK if not any((e[5]>=d[5] and e[6]<=d[6] and (e[5]>d[5] or e[6]<d[6])) for e in D.DECK)],key=lambda d:d[5])
# ensure all codes present; use full list sorted
opts=sorted(D.DECK,key=lambda d:d[5])
nextopt={}
for i,d in enumerate(opts):
    nextopt[d[0]]=[e[0] for e in opts[i+1:]]
def cost_deck(deck): return sum(D.zone_area(z)*D.DECK_BY_CODE[deck[z]]['cost'] for z in D.ZONES)
def cap(code): return D.DECK_BY_CODE[code]['nom']/2.35

def feas_capacity(deck,r):
    return all(r['zone_max'][z]<=cap(deck[z])+1e-9 for z in D.ZONES)

def greedy(deck,scen,target=0.525,maxit=25,verbose=True):
    ca={c[0]:1.125 for c in D.CHORD_LINES}
    cur=deck.copy(); r=G.eval_design(cur,ca,scenarios=scen)
    for it in range(maxit):
        md=max(r['maxdef'].values())
        if verbose: print('it',it,'def %.3f'%md,'cost',round(cost_deck(cur)),'feascap',feas_capacity(cur,r),'zones',{z:round(r['zone_max'][z]) for z in D.ZONES})
        if md<=target and feas_capacity(cur,r): break
        best=None
        for z in D.ZONES:
            c0=D.DECK_BY_CODE[cur[z]]['cost']; g0=D.DECK_BY_CODE[cur[z]]['Gp']
            for nc in nextopt[cur[z]]:
                d2=dict(cur); d2[z]=nc
                if cost_deck(d2)<=cost_deck(cur): continue
                r2=G.eval_design(d2,ca,scenarios=scen)
                md2=max(r2['maxdef'].values())
                # require feasible capacity overall
                if not feas_capacity(d2,r2): continue
                dcost=cost_deck(d2)-cost_deck(cur)
                gain=md-md2
                score=gain/dcost
                if best is None or score>best[0]: best=(score,z,nc,md2,dcost)
        if best is None or best[0]<=0:
            if verbose: print('no improving move')
            break
        score,z,nc,md2,dcost=best
        cur[z]=nc
        r=G.eval_design(cur,ca,scenarios=scen)
        if verbose: print('  ->',z,nc,'score %.2e'%score,'dcost',round(dcost),'def %.3f'%max(r['maxdef'].values()))
    return cur,r

if __name__=='__main__':
    base={z:'D22-36/4-2' for z in D.ZONES}
    t=time.time()
    deck,r=greedy(base,G.SC4)
