import numpy as np, fastmodel as F, fastdesign as G, a2data as D, wind as W
from final_design import DECK, CHORDS

def station_shear(m,u,line,frac):
    L=D.LINES[line]; s=L['s0']+frac*(L['s1']-L['s0'])
    tgt=np.array([s,L['fixed']]) if L['axis']=='x' else np.array([L['fixed'],s])
    sh,_=F.elem_shear(m,u); best=None
    for e,conn in enumerate(m.elems):
        xy=m.coords[list(conn)]
        on=any(abs(xy[k,1]-L['fixed'])<1e-6 for k in range(4)) if L['axis']=='x' else any(abs(xy[k,0]-L['fixed'])<1e-6 for k in range(4))
        if not on: continue
        d=np.hypot(m.centres[e,0]-tgt[0],m.centres[e,1]-tgt[1])
        if best is None or d<best[0]-1e-12: best=(d,e)
    return abs(sh[best[1]])

def collect(H):
    dg={z:D.DECK_BY_CODE[DECK[z]]['Gp'] for z in D.ZONES}
    ca={k:D.SEC_BY_CODE[v]['A'] for k,v in CHORDS.items()}
    m=F.build(H,dg,ca)
    res={}
    for sid,az,tors in G.SC:
        F.apply_scenario(m,az,tors); u=F.solve(m); r=F.results(m,u)
        sh=np.abs(r['shear'])
        zm={z:float(sh[m.zone_of_elem==z].max()) if (m.zone_of_elem==z).any() else 0.0 for z in D.ZONES}
        LL={}
        for line,L in D.LINES.items():
            tot=0.0
            for p in D.panels():
                if p['line']!=line: continue
                for b in W.patch_loads(p,az): tot+=b['Rroof']
            LL[line]=abs(tot*(0.75 if tors else 1.0))/(L['s1']-L['s0'])
        ps={}; pd=0.0
        for pr in m.piers:
            ud=u[2*pr['node']+pr['dof']]
            pd=max(pd,abs(ud)*12.0)
            ps[pr['panel']]=ps.get(pr['panel'],0.0)+pr['k']*ud
        res[sid]=dict(reac={k:float(abs(v)) for k,v in r['reac'].items()},line_load=LL,
                      defl={k:float(v) for k,v in r['defl'].items()},
                      chord={k:float(v) for k,v in r['chord'].items()},
                      station={line:{str(f):float(station_shear(m,u,line,f)) for f in [0.25,0.5,0.75]} for line in D.LINES},
                      panelshear={k:float(abs(v)) for k,v in ps.items()},
                      maxshear=float(sh.max()),pierdrift=float(pd),zone_max=zm,
                      bars=[(m.bars[i][3],float(r['bars'][i])) for i in range(len(m.bars))])
    return dict(elements=len(m.elems),nodes=m.nn,res=res)

if __name__=='__main__':
